'use strict';
const assert=require('node:assert/strict');
const fs=require('node:fs'),path=require('node:path');
const {chromium}=require('playwright');
const html=fs.readFileSync(path.resolve(__dirname,'../../index.html'),'utf8');
const css=[...html.matchAll(/<style[^>]*>([\s\S]*?)<\/style>/gi)].map(m=>m[1]).join('\n');
const long='超长记录与 ExampleLongUnbrokenNameOrURL0123456789'.repeat(7);
function fixture(width){const three=width<=760;return `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><style>${css}</style></head><body>
<section id="plansView" style="display:block;max-width:900px;margin:8px auto"><article class="plan-list-item"><div class="plan-drag-grip">⋮</div><div class="plan-row-main"><div class="plan-row-titleline"><div class="plan-row-title">${long}</div><span class="plan-row-status active">进行中</span></div><div class="plan-row-meta"><span>日期 2026-09-25</span><span>${long}</span></div></div><div class="plan-row-actions"><button class="plan-row-action primary">安排</button><button class="plan-row-action">归档</button></div></article><div class="calendar-panel week-panel"><div class="week-calendar-scroll"><div class="week-board density-comfortable ${three?'three-day-board':''}"><div class="week-corner"></div>${Array.from({length:three?3:7},()=>'<button class="week-day-head-cell"><strong>周三</strong><span>9/25</span></button>').join('')}<div class="week-time-label"><strong>晚上</strong><span>18:00</span></div>${Array.from({length:three?3:7},(_,i)=>`<div class="week-slot occupancy-2"><span class="week-slot-capacity">2/4</span><div class="week-slot-events"><div class="calendar-event plan-role-kp" draggable="true"><div class="calendar-event-time">19:00–22:00</div><div class="calendar-event-name">测试长模组标题 ${long}</div><div class="calendar-event-meta"><span class="event-status">进行中</span><span>4 PL</span></div><button type="button" class="calendar-event-remove" aria-label="取消安排">×</button></div></div></div>`).join('')}</div></div></div></section>
<section id="recordsView" style="display:block;max-width:760px;margin:12px auto"><article class="table-record"><header class="table-record-head"><div class="table-record-title-row"><strong class="record-title-name">${long}</strong></div><div class="table-record-summary"><span class="record-summary-chip">已结团</span></div></header><button class="table-record-collapse-strip"><span class="record-collapse-strip-label">展开本桌详情</span><span class="record-collapse-strip-summary">4 人</span></button><div class="table-record-body"><div class="record-view-mode"><section class="record-view-summary"><div class="record-view-fact"><span>KP</span><strong>${long}</strong></div><div class="record-view-fact"><span>日期</span><strong>2026-09-25</strong></div><div class="record-view-fact"><span>Log</span><strong class="record-view-log-value"><span class="record-view-log-links"><span class="record-view-log-item"><span class="record-view-log-note">${long}</span><a href="#">https://example.invalid/${long}</a></span></span></strong></div><div class="record-view-fact"><span>桌名</span><strong>${long}</strong></div></section><section class="record-view-cast"><div class="record-view-section-title"><strong>PL / PC</strong><span>4 人</span></div><div class="record-view-people"><div class="record-view-person"><strong class="record-view-person-name">${long}</strong><span class="record-view-person-meta">HO 1　PC ${long}</span></div></div></section><details class="record-view-extra" open><summary>本桌补充 · 2项</summary><div><p>${long}\n第二段内容保留换行。</p></div></details></div><div class="record-section"><div class="record-section-note">Log编辑</div><div class="multi-log-list"><div class="multi-log-row"><span class="multi-log-index">1</span><input class="text-input multi-log-label-input" value="测试"><input class="text-input multi-log-url-input" value="https://example.invalid/"><button class="multi-log-remove" type="button">×</button></div></div></div></div></article></section></body></html>`;}
(async()=>{const browser=await chromium.launch({headless:true,args:['--no-sandbox']});try{for(const width of [1440,900,390,320]){const page=await browser.newPage({viewport:{width,height:900}}),errors=[];page.on('pageerror',e=>errors.push(String(e)));await page.setContent(fixture(width));const d=await page.evaluate(()=>{const r=s=>document.querySelector(s).getBoundingClientRect(),f=s=>parseFloat(getComputedStyle(document.querySelector(s)).fontSize),el=s=>document.querySelector(s);return {overflow:document.documentElement.scrollWidth-innerWidth,btn:r('#plansView .calendar-event-remove').toJSON(),evt:r('#plansView .calendar-event').toJSON(),evtName:r('#plansView .calendar-event-name').toJSON(),font:f('#plansView .calendar-event-name'),recordFont:f('#recordsView .record-view-fact strong'),noteFont:f('#recordsView .record-view-extra p'),collapse:r('#recordsView .table-record-collapse-strip').height,cols:getComputedStyle(el('#recordsView .record-view-summary')).gridTemplateColumns.split(' ').length,logScroll:el('#recordsView .record-view-log-links a').scrollWidth-el('#recordsView .record-view-log-links a').clientWidth,noteScroll:el('#recordsView .record-view-extra p').scrollWidth-el('#recordsView .record-view-extra p').clientWidth,logDelete:r('#recordsView .multi-log-remove').width,planAction:r('#plansView .plan-row-action').height};});assert(d.overflow<=1,`${width} document overflow ${d.overflow}`);assert(d.btn.width>=(width<=760?30:28),`${width} cancellation target`);assert(d.evtName.right<=d.btn.left+2||d.evtName.bottom<=d.btn.top+1||d.btn.bottom<=d.evtName.top+1,`${width} cancellation overlaps title`);if(width<=760)assert(d.evtName.width>=20,`${width} calendar title squeezed to ${d.evtName.width}px`);assert(d.font>=11,`${width} calendar title too small`);assert(d.recordFont>=12&&d.noteFont>=12,`${width} record text too small`);assert(d.logScroll<=1&&d.noteScroll<=1,`${width} long record text clipped`);assert(d.collapse>=(width<=760?44:40),`${width} collapse touch`);assert(d.cols===(width<=760?2:4),`${width} record facts columns ${d.cols}`);if(width<=760){assert(d.logDelete>=42,`${width} log delete too narrow`);assert(d.planAction>=42,`${width} plan action too short`);}assert.equal(errors.length,0,`${width} page errors`);console.log(`${width}px: no overflow; cancel ${d.btn.width}px; columns ${d.cols}; record ${d.recordFont}px; collapsed ${d.collapse}px; no errors`);await page.close();}}finally{await browser.close();}})().catch(e=>{console.error(e);process.exitCode=1});
